<?php if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: index.php');exit();}$raw=trim($_POST['name']??'');$ageRaw=$_POST['age']??'';if($raw===''||filter_var($ageRaw,FILTER_VALIDATE_INT)===false||(int)$ageRaw<0||(int)$ageRaw>120){http_response_code(400);exit('Please enter a valid name and age.');}$name=htmlspecialchars($raw,ENT_QUOTES,'UTF-8');$age=(int)$ageRaw;$ok=$age>=18;?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verification Result</title><link rel="stylesheet" href="../assets/css/program.css"></head><body><header class="nav"><a class="brand" href="../"><b>P</b> PHP LAB</a><a class="back" href="../">← Programs home</a></header><main class="wrap"><div class="eyebrow">PROGRAM C · VERIFICATION RESULT</div><h1 class="title">Your result.</h1><p class="subtitle">The verification is complete.</p><section class="panel result"><div class="symbol" style="<?= $ok?'':'background:#fff0f0;color:#d45e67' ?>"><?= $ok?'✓':'!' ?></div><h2><?= $ok?'Welcome to this site!':'Access not authorized' ?></h2><p><?= $ok?"Hello, $name. You are authorized to visit the site.":"Hello, $name, you are not authorized to visit the site." ?></p><div class="stat"><small>AGE ENTERED</small><?= $age ?> years</div><br><a class="secondary" href="index.php">Check another age</a></section></main><footer class="footer">PHP LAB STUDIO · PROGRAM C</footer></body></html>